INSERT INTO notices (category, title, body, pinned, views, created_at) VALUES ('공지', 'EzPark 서비스 정식 오픈', 'AI 영상 인지 기반 주차관제·유도 플랫폼 EzPark가 정식 오픈했습니다.', FALSE, 3502, '2026-08-01 09:00:00');
INSERT INTO notices (category, title, body, pinned, views, created_at) VALUES ('점검', 'CCTV 인지 모델 v3.2 배포에 따른 일시 지연 안내', '인지 정확도 향상을 위해 모델이 업데이트되었습니다.', FALSE, 388, '2026-08-21 09:00:00');
INSERT INTO notices (category, title, body, pinned, views, created_at) VALUES ('이벤트', '전기차 충전구역 실시간 안내 베타 오픈', '전기차 충전 가능 면을 지도와 유도 화면에서 확인할 수 있습니다.', FALSE, 1120, '2026-09-02 09:00:00');
INSERT INTO notices (category, title, body, pinned, views, created_at) VALUES ('공지', '개인정보 처리방침 개정 안내 (2026.10.01 시행)', '차량번호 영상 데이터 비식별화 처리 기준이 추가되었습니다.', FALSE, 455, '2026-09-17 09:00:00');
INSERT INTO notices (category, title, body, pinned, views, created_at) VALUES ('공지', '전국 공영주차장 10곳 정보 연동 (서울·인천·경기·대전·전북·대구·부산·강원·제주)', '운영기관 공개자료와 공공데이터포털 전국주차장정보표준데이터를 기준으로 전국 공영주차장 10곳의 주소·주차면수·요금 정보를 제공합니다. 잔여면 정보는 데모 시뮬레이션입니다.', FALSE, 731, '2026-09-24 09:00:00');
INSERT INTO notices (category, title, body, pinned, views, created_at) VALUES ('이벤트', '첫 예약 고객 주차요금 30% 할인 이벤트', '10월 한 달간 EzPark로 첫 예약 시 주차요금 30%를 할인해 드립니다. (최대 1만원)', FALSE, 2310, '2026-10-01 09:00:00');
INSERT INTO notices (category, title, body, pinned, views, created_at) VALUES ('점검', '10월 18일(토) 02:00~05:00 정기 서버 점검 안내', '안정적인 서비스 제공을 위해 정기 점검이 진행됩니다. 점검 시간 동안 예약·결제 기능 이용이 제한됩니다.', TRUE, 842, '2026-10-08 09:00:00');
INSERT INTO notices (category, title, body, pinned, views, created_at) VALUES ('공지', 'EzPark 2.0 – AI 주차 유도 경로 안내 기능 업데이트', '입구에서 추천 주차면까지 실시간 경로를 안내하는 기능이 추가되었습니다. 주차 유도 메뉴에서 층을 선택하고 빈자리를 누르면 경로가 표시됩니다.', TRUE, 1284, '2026-10-10 09:00:00');
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('이용', '빈자리 정보는 얼마나 정확한가요?', 'CCTV 영상을 AI 모델이 실시간으로 분석해 주차면 점유를 판단합니다. 현재 평균 인지 정확도는 97.8%이며, 3~5초 간격으로 갱신됩니다.', 1);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('이용', '주차 유도 경로는 어떻게 안내되나요?', '주차 유도 메뉴에서 주차장과 층을 선택한 뒤 빈자리를 누르면 입구에서 해당 주차면까지 최단 경로가 표시됩니다. "AI 추천" 버튼을 누르면 가장 가까운 빈자리를 자동으로 추천합니다.', 2);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('예약', '예약은 언제까지 취소할 수 있나요?', '입차 예정 시간 30분 전까지 무료 취소가 가능하며, 이후에는 기본요금 1회분이 부과됩니다.', 3);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('예약', '예약한 자리에 다른 차량이 주차되어 있으면요?', 'AI가 예약면의 무단 점유를 감지하면 관제센터에 알림이 전송되고, 동일 층의 대체 주차면을 즉시 배정해 드립니다.', 4);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('결제', '어떤 결제 수단을 지원하나요?', '신용/체크카드, 카카오페이, 네이버페이, 토스페이를 지원합니다. 기업 고객은 월 정산(세금계산서)도 가능합니다.', 5);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('결제', '영수증은 어디서 확인하나요?', '마이페이지 > 이용내역에서 건별 영수증을 확인하고 PDF로 저장할 수 있습니다.', 6);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('계정', '차량은 몇 대까지 등록할 수 있나요?', '개인 회원은 최대 5대, 기업 회원은 제한 없이 등록할 수 있습니다.', 7);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('계정', '소셜 계정으로 가입할 수 있나요?', 'Google 계정 로그인을 지원하며(Firebase 인증), 카카오·네이버 로그인은 순차 오픈 예정입니다.', 8);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('기업', '기존 CCTV를 그대로 사용할 수 있나요?', '네, 해상도 1080p 이상의 IP 카메라라면 대부분 그대로 연동 가능합니다. 현장 실사 후 최적 화각을 안내해 드립니다.', 9);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('기업', '도입까지 얼마나 걸리나요?', '500면 기준 현장 실사부터 운영 오픈까지 평균 2~3주가 소요됩니다.', 10);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('기업', '영상 데이터의 개인정보는 어떻게 보호되나요?', '차량번호와 얼굴은 엣지 단계에서 비식별화되며, 원본 영상은 저장하지 않고 메타데이터만 암호화하여 보관합니다.', 11);
INSERT INTO faqs (category, question, answer, sort_order) VALUES ('이용', '전기차 충전 구역도 안내되나요?', '네, 주차장 찾기에서 "전기차" 필터를 사용하거나 주차 유도 화면에서 파란색 EV 면을 확인할 수 있습니다.', 12);
